function Card({
  card,
  accent,
  index,
  frame,
}: {
  card: CardDef;
  accent: string;
  index: number;
  frame: number;
}) {
  const t = noise(index, frame) * 6.28;
  const baseStyle: React.CSSProperties = {
    position: "absolute",
    left: card.x,
    top: card.y,
    width: card.w,
    height: card.h,
    borderRadius: 18,
    background: "linear-gradient(180deg, #131313 0%, #0a0a0a 100%)",
    border: "1px solid rgba(255,255,255,0.07)",
    overflow: "hidden",
    padding: 18,
    color: "white",
    display: "flex",
    flexDirection: "column",
  };

  const labelEl = card.label ? (
    <div
      style={{
        fontSize: 12,
        fontWeight: 600,
        color: "rgba(255,255,255,0.55)",
        letterSpacing: "0.04em",
        textTransform: "uppercase",
        marginBottom: 8,
      }}
    >
      {card.label}
    </div>
  ) : null;

  if (card.kind === "chart") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <div style={{ flex: 1 }}>
          <ChartCard accent={accent} t={t} />
        </div>
      </div>
    );
  }
  if (card.kind === "bars") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <div style={{ flex: 1 }}>
          <BarsCard accent={accent} t={t} />
        </div>
      </div>
    );
  }
  if (card.kind === "counter") {
    const v = Math.floor(1200 + noise(index, frame) * 800);
    return (
      <div style={baseStyle}>
        {labelEl}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-start",
            fontSize: 56,
            fontWeight: 700,
            letterSpacing: "-0.04em",
            color: "white",
          }}
        >
          {v.toLocaleString()}
        </div>
        <div style={{ fontSize: 12, color: accent, fontWeight: 600 }}>
          +{(noise(index + 1, frame) * 12).toFixed(1)}%
        </div>
      </div>
    );
  }
  if (card.kind === "stat") {
    const v = (95 + noise(index, frame) * 5).toFixed(2);
    return (
      <div style={baseStyle}>
        {labelEl}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "center",
            fontSize: 48,
            fontWeight: 700,
            letterSpacing: "-0.03em",
          }}
        >
          {v}
          <span
            style={{
              fontSize: 20,
              color: "rgba(255,255,255,0.5)",
              marginLeft: 4,
            }}
          >
            %
          </span>
        </div>
      </div>
    );
  }
  if (card.kind === "code") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <div style={{ flex: 1, display: "flex", alignItems: "center" }}>
          <div style={{ width: "100%" }}>
            <CodeCard />
          </div>
        </div>
      </div>
    );
  }
  if (card.kind === "logo") {
    return (
      <div style={{ ...baseStyle, padding: 0 }}>
        <LogoCard accent={accent} hue={card.hue} />
      </div>
    );
  }
  // gradient
  return (
    <div style={{ ...baseStyle, padding: 0 }}>
      <GradientCard hue={card.hue} />
    </div>
  );
}

function InfiniteBentoPanBase({
  panSpeed = 1,
  accentColor = "#7c3aed",
  speed = 1,
  className,
}: InfiniteBentoPanProps) {
  const glide = useGlide();
  const frame = useSceneFrame() * speed;
  const { durationInFrames, width, height } = useSceneConfig();

  const maxX = SUPER_W - width;
  const maxY = SUPER_H - height;

  // diagonal pan: from top-left toward bottom-right
  const t = interpolate(frame, [0, durationInFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const px = t * maxX * Math.min(1, panSpeed);
  const py = t * maxY * Math.min(1, panSpeed);
  const panning = t > 0 && t < 1 && py !== 0;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        background: "transparent",
        overflow: "hidden",
        fontFamily: FONT_FAMILY,
      }}
    >
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: SUPER_W,
          height: SUPER_H,
          translate: `${-px}px ${-py}px`,
          transform: glide(panning),
        }}
      >
        {CARDS.map((c, i) => (
          <Card key={i} card={c} accent={accentColor} index={i} frame={frame} />
        ))}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(circle at center, transparent 30%, rgba(0,0,0,0.85) 80%, #000 100%)",
          pointerEvents: "none",
        }}
      />
    </div>
  );
}

