    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["panSpeed","accentColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  panSpeed: 1,
  accentColor: "#7c3aed",
  speed: 1,
};

type InfiniteBentoPanElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof InfiniteBentoPanBase>;

const InfiniteBentoPanInner = forwardRef<
  HTMLDivElement,
  InfiniteBentoPanElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<InfiniteBentoPan>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <InfiniteBentoPanBase
          {...(componentProps as unknown as ComponentProps<typeof InfiniteBentoPanBase>)}
        />
      </div>
    </Sequence>
  );
});

export const InfiniteBentoPan = Interactive.withSchema({
  Component: InfiniteBentoPanInner,
  componentName: "<InfiniteBentoPan>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
